import os
import subprocess

# Dump the contents of file_check.sh if present
for base in [".", os.path.join(".codex", "skills", "xlsx")]:
    p = os.path.join(base, "resources", "file_check.sh")
    if os.path.exists(p):
        print("=" * 20, p, "=" * 20)
        try:
            with open(p, "r", encoding="utf-8", errors="replace") as f:
                print(f.read())
        except Exception as e:
            print("could not read:", repr(e))

# Search a bit wider for budget.xlsx
print("=" * 20, "SEARCH budget.xlsx", "=" * 20)
start = os.path.abspath(".")
print("searching under", start)
for root, dirs, files in os.walk(start):
    dirs[:] = [d for d in dirs if not d.startswith(".")]
    for f in files:
        if "budget" in f.lower():
            print(os.path.join(root, f))

# Also check parent dirs one level up (may be where task files live)
parent = os.path.dirname(start)
if parent and os.path.isdir(parent):
    print("parent dir listing:", os.listdir(parent)[:100])

import os

start = os.path.abspath(".")
print("CWD contents:", os.listdir(start))

# Walk up a few levels looking for budget files (the file the user asked to read)
targets = ["budget.xlsx", "budget.csv", "Budget.xlsx"]
found = []
for level in range(4):
    base = start
    for _ in range(level):
        base = os.path.dirname(base)
    if not base or not os.path.isdir(base):
        break
    for root, dirs, files in os.walk(base):
        dirs[:] = [d for d in dirs if not d.startswith(".") and d != "node_modules"]
        for f in files:
            if f.lower() in [t.lower() for t in targets]:
                found.append(os.path.join(root, f))
    if found:
        break

print("budget file candidates:", found)

